/* From Uiverse.io by Navarog21 - Tags:  */
.__UIV_SCOPE__ .radioContainer {
  display: flex;
  justify-content: space-between;
  position: relative;
  width: 220px;
}

.__UIV_SCOPE__ .radioButton {
  display: none;
}

.__UIV_SCOPE__ .radioContainer .container {
  display: inline-flex;
  justify-content: center;
  align-items: center;
  position: relative;
  transition: 0.8s;
  cursor: pointer;
  width: 65px;
  height: 65px;
  background-image: linear-gradient(to top, #00c6fb 0%, #005bea 100%);
  clip-path: polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%);
  box-shadow: 0 0 5px inset white;
}

.__UIV_SCOPE__ .border {
  position: absolute;
  background-color: #212121;
  width: 100%;
  height: 100%;
  transform: scale(0.7) rotate(30deg);
  transition: 0.3s;
  clip-path: polygon(0% 0%, 0% 100%, 25% 100%, 25% 25%, 75% 25%, 75% 75%, 25% 75%, 25% 100%, 100% 100%, 100% 0%);
}

.__UIV_SCOPE__ .border2 {
  position: absolute;
  background-color: #212121;
  width: 100%;
  height: 100%;
  transform: scale(0.45);
  transition: 0.2s;
  clip-path: polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%);
}

.__UIV_SCOPE__ .radioContainer input[type="radio"]:checked + .container {
  filter: hue-rotate(330deg);
  animation: 2s linear checked;
}

.__UIV_SCOPE__ .radioContainer input[type="radio"]:checked + .container .circle {
  transform: scale(0.8);
}

.__UIV_SCOPE__ .radioContainer input[type="radio"]:checked + .container .border {
  animation: 4s linear infinite reverse rotateBorder;
}

.__UIV_SCOPE__ .radioContainer input[type="radio"]:checked + .container .border2 {
  animation: 2s linear reverse rotateBorder2;
}

.__UIV_SCOPE__ .circle {
  background-image: linear-gradient(to top, #00c6fb 0%, #005bea 100%);
  border-radius: 100%;
  width: 22%;
  height: 22%;
  transition: 0.25s;
  z-index: 2;
  transform: scale(0);
}

.__UIV_SCOPE__ .radioContainer .container:hover .circle {
  transform: scale(0.8);
  box-shadow: 0 20px 20px #00c6fb;
}

@keyframes checked {
  0% {
    transform: rotate(0deg) scale(1);
  }

  50% {
    transform: rotate(0deg) scale(1.07);
  }

  100% {
    transform: rotate(360deg) scale(1);
  }
}

@keyframes rotateBorder {
  0% {
    transform: scale(0.7) rotate(0deg);
  }

  50% {
    transform: scale(0.7) rotate(0deg);
  }

  100% {
    transform: scale(0.7)rotate(360deg);
  }
}

@keyframes rotateBorder2 {
  0% {
    transform: scale(0.51) rotate(30deg);
  }

  50% {
    transform: scale(0.51) rotate(0deg);
  }

  100% {
    transform: scale(0.51) rotate(360deg);
  }
}
